<?php\ndeclare(strict_types=1);\n\nnamespace Acme\\Reporting\\Template;\n\nabstract class ReportBuilder\n{\n    /**\n     * Template method - final to enforce algorithm skeleton.\n     * Defines the不变 algorithm structure with hook extension points.\n     */\n    final public function generate(ReportRequest $request): ReportResult\n    {\n        $this->logReport('Starting report generation');\n        $this->validateInputs($request);\n        $data = $this->fetchData($request);\n        $filtered = $this->applyFilters($data, $request->getFilters());\n        $formatted = $this->formatOutput($filtered);\n        $this->sendDelivery($formatted, $request->getRecipient());\n        $this->logReport('Report generation completed');\n        return new ReportResult($formatted, true);\n    }\n\n    /**\n     * Hook method - override for custom logging behavior.\n     * Default implementation does nothing.\n     */\n    protected function logReport(string $message): void\n    {\n        // Default: no-op. Override for custom logging.\n    }\n\n    /**\n     * Abstract method - MUST be implemented by subclasses.\n     */\n    abstract protected function validateInputs(ReportRequest $request): void;\n\n    /**\n     * Abstract method - MUST be implemented by subclasses.\n     */\n    abstract protected function fetchData(ReportRequest $request): array;\n\n    /**\n     * Abstract method - MUST be implemented by subclasses.\n     */\n    abstract protected function applyFilters(array $data, array $filters): array;\n\n    /**\n     * Abstract method - MUST be implemented by subclasses.\n     */\n    abstract protected function formatOutput(array $data): string;\n\n    /**\n     * Hook method - override for custom delivery behavior.\n     * Default sends email.\n     */\n    protected function sendDelivery(string $content, string $recipient): void\n    {\n        mail($recipient, 'Report', $content);\n    }\n}\n\nclass SalesReportBuilder extends ReportBuilder\n{\n    protected function validateInputs(ReportRequest $request): void\n    {\n        if ($request->getStartDate() === null) {\n            throw new \\InvalidArgumentException('Start date required for sales report');\n        }\n    }\n\n    protected function fetchData(ReportRequest $request): array\n    {\n        // Fetch sales data from database\n        return [['product' => 'Widget', 'amount' => 100]];\n    }\n\n    protected function applyFilters(array $data, array $filters): array\n    {\n        return array_filter($data, fn($row) => $row['amount'] > ($filters['min_amount'] ?? 0));\n    }\n\n    protected function formatOutput(array $data): string\n    {\n        $output = \"Sales Report\\n\";\n        foreach ($data as $row) {\n            $output .= sprintf(\"%s: $%d\\n\", $row['product'], $row['amount']);\n        }\n        return $output;\n    }\n}\n\nclass InventoryReportBuilder extends ReportBuilder\n{\n    protected function validateInputs(ReportRequest $request): void\n    {\n        if (empty($request->getWarehouseId())) {\n            throw new \\InvalidArgumentException('Warehouse ID required');\n        }\n    }\n\n    protected function fetchData(ReportRequest $request): array\n    {\n        return [['item' => 'Box', 'quantity' => 50]];\n    }\n\n    protected function applyFilters(array $data, array $filters): array\n    {\n        return array_filter($data, fn($row) => $row['quantity'] < ($filters['max_quantity'] ?? PHP_INT_MAX));\n    }\n\n    protected function formatOutput(array $data): string\n    {\n        $output = \"Inventory Report\\n\";\n        foreach ($data as $row) {\n            $output .= sprintf(\"%s: %d units\\n\", $row['item'], $row['quantity']);\n        }\n        return $output;\n    }\n}
